    title: "闲居初夏午睡起二首·其一",
    entries: ["gushi-gs-55", "tangshi-ts-389", "tangshi-ts-390"],
    text: "梅子留酸软齿牙，芭蕉分绿与窗纱。\n日长睡起无情思，闲看儿童捉柳花。",
    translation: "梅子的酸味还留在齿间，牙齿都觉得发软；芭蕉的绿意分了一片给窗纱。\n白昼漫长，午睡起来没什么兴致，闲着看孩子们追逐捕捉柳絮。",
