    text: "岐王宅里寻常见，崔九堂前几度闻。\n正是江南好风景，落花时节又逢君。",
    translation: "当年在岐王的府宅里常常看到你，在崔九的堂前也多次听过你的歌唱。如今正是江南风景最好的时候，在这落花的时节又遇到了你。",
