    title: "行军九日思长安故园",
    entries: ["poems-cz7-07", "tangshi-ts-414"],
    text: "强欲登高去，无人送酒来。\n遥怜故园菊，应傍战场开。",
    translation: "勉强想要登高去，却没有人送酒来。遥想故乡长安的菊花，大概只能靠着战场开放了。",
