    entries: ["poems-cz7-08", "tangshi-ts-270"],
    text: "回乐烽前沙似雪，受降城外月如霜。\n不知何处吹芦管，一夜征人尽望乡。",
    translation: "回乐峰前的沙地白得像雪，受降城外的月色冷得像霜。不知道哪里吹起了芦管，一夜之间，出征的人都望着故乡。",
    translationSource: "school",
    version: "18sphr1"
