    entries: ["poems-cz7-10", "tangshi-ts-295"],
    text: "君问归期未有期，巴山夜雨涨秋池。\n何当共剪西窗烛，却话巴山夜雨时。",
    translation: "你问我什么时候回去，我还没有确定的日期；巴山的夜雨下个不停，秋水涨满了池塘。什么时候我们才能在西窗下一起剪烛长谈，再来说说今夜巴山夜雨时我的心情。",
