    entries: ["poems-cz7-14", "tangshi-ts-223"],
    text: "独坐幽篁里，弹琴复长啸。\n深林人不知，明月来相照。",
    translation: "独自坐在幽深的竹林里，一边弹琴一边长声呼啸。深林中没有别人知道，只有明月来与我相伴。",
