    entries: ["poems-cz7-15", "tangshi-ts-415"],
    text: "谁家玉笛暗飞声，散入春风满洛城。\n此夜曲中闻折柳，何人不起故园情。",
    translation: "是谁家的玉笛暗暗传出悠扬的乐声，随着春风飘满整个洛阳城。今夜听到曲中的《折杨柳》，哪个人不生出思念故乡的感情呢？",
