    title: "逢入京使",
    entries: ["poems-cz7-16", "tangshi-ts-261"],
    text: "故园东望路漫漫，双袖龙钟泪不干。\n马上相逢无纸笔，凭君传语报平安。",
    translation: "向东望着故乡，路途遥远漫长，两只袖子沾满泪水，擦也擦不干。在马上与你相遇，没有纸笔写信，只好请你捎个口信，告诉我的家人我一切平安。",
