    entries: ["poems-cz7-17", "tangshi-ts-416"],
    text: "草树知春不久归，百般红紫斗芳菲。\n杨花榆荚无才思，惟解漫天作雪飞。",
    translation: "花草树木知道春天不久就要归去，于是万紫千红，争相斗艳。只有杨花和榆荚没有才思，只知道像雪花一样漫天飞舞。",
