    entries: ["poems-cz7-18", "tangshi-ts-34"],
    text: "前不见古人，后不见来者。\n念天地之悠悠，独怆然而涕下！",
    translation: "往前看不到古代的贤君，往后也看不到后世的明主。想到天地是这样辽阔久远，我独自悲伤，泪流满面！",
