    id: "poems-cz8-09",
    title: "钱塘湖春行",
    entries: ["poems-cz8-09", "tangshi-ts-418"],
    text: "孤山寺北贾亭西，水面初平云脚低。\n几处早莺争暖树，谁家新燕啄春泥。\n乱花渐欲迷人眼，浅草才能没马蹄。\n最爱湖东行不足，绿杨阴里白沙堤。",
    translation: "从孤山寺的北面到贾公亭的西面，湖面春水刚刚涨平，白云低垂，几乎与湖面相接。几处早出的黄莺争着飞向向阳的树木，谁家新来的燕子啄着春泥在筑巢。繁多的野花渐渐要使人眼花缭乱，浅浅的春草刚刚能够遮住马蹄。我最喜爱湖东的景色，怎么走也走不够，绿杨荫里那一道白沙堤。",
