    id: "poems-cz8-27",
    title: "送友人",
    entries: ["poems-cz8-27", "tangshi-ts-107"],
    text: "青山横北郭，白水绕东城。\n此地一为别，孤蓬万里征。\n浮云游子意，落日故人情。\n挥手自兹去，萧萧班马鸣。",
