    entries: ["poems-xx2-10", "tangshi-ts-156"],
    text: "离离原上草，一岁一枯荣。\n野火烧不尽，春风吹又生。\n远芳侵古道，晴翠接荒城。\n又送王孙去，萋萋满别情。",
