    id: "tangshi-ts-124",
    title: "酬张少府",
    entries: ["tangshi-ts-124"],
    text: "晚年惟好静，万事不关心。\n自顾无长策，空知返旧林。\n松风吹解带，山月照弹琴。\n君问穷通理，渔歌入浦深。",
    translation: "晚年只喜欢清静，万事都不关心。自思没有好的计策，只知道回归旧日的山林。松风吹来解开衣带，山月照着弹琴。你问穷困与通达的道理，渔歌正传入那深深的浦口。",
