    id: "tangshi-ts-127",
    title: "终南别业",
    entries: ["tangshi-ts-127"],
    text: "中岁颇好道，晚家南山陲。\n兴来每独往，胜事空自知。\n行到水穷处，坐看云起时。\n偶然值林叟，谈笑无还期。",
