    id: "tangshi-ts-13",
    title: "青溪",
    entries: ["tangshi-ts-13"],
    text: "言入黄花川，每逐青溪水。\n随山将万转，趣途无百里。\n声喧乱石中，色静深松里。\n漾漾泛菱荇，澄澄映葭苇。\n我心素已闲，清川澹如此。\n请留盘石上，垂钓将已矣。",
    translation: "我进入黄花川，常常追随着青溪的水流。随着山势千回万转，路程却不到百里。水声在乱石间喧响，水色在深松林里幽静。水波荡漾漂着菱叶荇菜，水光澄澈映着芦苇。我的心本来就很闲适，清澈的溪流也如此恬淡。请让我留在溪边的盘石上，垂钓度日就此了此一生吧。",
