    title: "宴梅道士山房",
    entries: ["tangshi-ts-130"],
    text: "林卧愁春尽，搴帷览物华。\n忽逢青鸟使，邀入赤松家。\n金灶初开火，仙桃正发花。\n童颜若可驻，何惜醉流霞。",
