    id: "tangshi-ts-14",
    title: "渭川田家",
    entries: ["tangshi-ts-14"],
    text: "斜阳照墟落，穷巷牛羊归。\n野老念牧童，倚杖候荆扉。\n雉雊麦苗秀，蚕眠桑叶稀。\n田夫荷锄立，相见语依依。\n即此羡闲逸，怅然吟式微。",
    translation: "斜阳照着村庄，深巷里牛羊回来了。老人惦记着放牧的孩子，拄着拐杖在柴门前等候。野鸡鸣叫，麦苗正在抽穗；蚕儿休眠，桑叶已经稀疏。农夫扛着锄头站立，彼此相见话语依依。看到这些，我羡慕这种闲适安逸，惆怅地吟起《式微》来。",
