    title: "云阳馆与韩绅宿别",
    entries: ["tangshi-ts-151"],
    text: "故人江海别，几度隔山川。\n乍见翻疑梦，相悲各问年。\n孤灯寒照雨，深竹暗浮烟。\n更有明朝恨，离杯惜共传。",
