    id: "tangshi-ts-177",
    title: "送魏万之京",
    entries: ["tangshi-ts-177"],
    text: "朝闻游子唱离歌，昨夜微霜初渡河。\n鸿雁不堪愁里听，云山况是客中过。\n关城树色催寒近，御苑砧声向晚多。\n莫见长安行乐处，空令岁月易蹉跎。",
