    id: "tangshi-ts-18",
    title: "宿业师山房期丁大不至",
    entries: ["tangshi-ts-18"],
    text: "夕阳度西岭，群壑倏已暝。\n松月生夜凉，风泉满清听。\n樵人归欲尽，烟鸟栖初定。\n之子期宿来，孤琴候萝径。",
    translation: "夕阳越过西边的山岭，各条山谷忽然间已经昏暗。松间的月亮带来夜的凉意，风声泉声充满了清幽的听觉。砍柴的人差不多都回家了，暮烟中的鸟儿也刚刚安歇。你约定今晚来过夜，我抱着孤琴在藤萝小径上等候。",
