    title: "西塞山怀古",
    entries: ["tangshi-ts-208"],
    text: "王濬楼船下益州，金陵王气黯然收。\n千寻铁锁沉江底，一片降幡出石头。\n人世几回伤往事，山形依旧枕寒流。\n今逢四海为家日，故垒萧萧芦荻秋。",
    translation: "王濬的战船从益州顺流而下，金陵的王气黯然收去。千寻长的铁锁沉入江底，一片投降的旗帜从石头城上举出。人世间几次为往事感伤，山的形状依旧枕着寒流。如今正逢四海一家的日子，旧日的营垒萧萧、芦荻在秋风中摇动。",
