    title: "遣悲怀·其一",
    entries: ["tangshi-ts-209"],
    text: "谢公最小偏怜女，自嫁黔娄百事乖。\n顾我无衣搜荩箧，泥他沽酒拔金钗。\n野蔬充膳甘长藿，落叶添薪仰古槐。\n今日俸钱过十万，与君营奠复营斋。",
    translation: "你像谢公最疼爱的小女儿，自从嫁给我这贫士便百事不顺。看我没有衣服穿就翻箱倒柜寻找，缠着你去买酒、你便拔下金钗。用野菜充饥、甘心吃豆叶，靠落叶添柴、仰仗老槐树。如今我的俸钱已超过十万，却只能为你营办祭奠与斋事。",
