    title: "春泛若耶溪",
    entries: ["tangshi-ts-21"],
    text: "幽意无断绝，此去随所偶。\n晚风吹行舟，花路入溪口。\n际夜转西壑，隔山望南斗。\n潭烟飞溶溶，林月低向后。\n生事且弥漫，愿为持竿叟。",
    translation: "幽居的意趣没有断绝，此番出行随遇而安。晚风吹着行船，沿着花径进入溪口。入夜后船转入西边的山谷，隔着山望见南斗星。潭上雾气溶溶飘飞，林中月影低低地向后移去。人生世事茫茫无边，我愿做个持竿垂钓的老翁。",
