    id: "tangshi-ts-273",
    title: "后宫词",
    entries: ["tangshi-ts-273"],
    text: "泪湿罗巾梦不成，夜深前殿按歌声。\n红颜未老恩先断，斜倚薰笼坐到明。",
    translation: "泪水沾湿罗巾、睡不成梦，夜深时前殿传来按拍而歌的声音。红颜还未衰老、恩宠先已断绝，斜倚着薰笼一直坐到天明。",
