    title: "集灵台·其一",
    entries: ["tangshi-ts-275"],
    text: "日光斜照集灵台，红树花迎晓露开。\n昨夜上皇新授箓，太真含笑入帘来。",
    translation: "日光斜照着集灵台，红树的花迎着晓露开放。昨夜上皇新受符箓，太真含笑走进帘中来。",
