    entries: ["chengyu-cy-465", "tangshi-ts-276"],
    text: "虢国夫人承主恩，平明骑马入宫门。\n却嫌脂粉污颜色，淡扫蛾眉朝至尊。",
    translation: "虢国夫人承受君主的恩宠，天明时骑马进入宫门。却嫌脂粉污了容颜，只淡淡地画了眉毛去朝见天子。",
    translationSource: "public-domain",
