    text: "落魄江湖载酒行，楚腰纤细掌中轻。\n十年一觉扬州梦，赢得青楼薄幸名。",
    translation: "落魄江湖、带着酒行走，楚地的腰肢纤细、舞姿轻盈能在掌上起舞。十年一觉、如同扬州的梦，只落得青楼里一个薄情的名声。",
