    title: "秋夕",
    entries: ["tangshi-ts-285"],
    text: "银烛秋光冷画屏，轻罗小扇扑流萤。\n天阶夜色凉如水，卧看牵牛织女星。",
    translation: "银烛的秋光映着清冷的画屏，她拿着轻罗小扇扑打流萤。天阶上的夜色凉如水，躺着看牵牛星与织女星。",
