    entries: ["tangshi-ts-286"],
    text: "繁华事散逐香尘，流水无情草自春。\n日暮东风怨啼鸟，落花犹似坠楼人。",
    translation: "繁华的往事随着香尘散去，流水无情、春草自绿。日暮时东风吹来、啼鸟哀怨，落花还像是那坠楼的人。",
