    entries: ["tangshi-ts-287"],
    text: "娉娉袅袅十三余，豆蔻梢头二月初。\n春风十里扬州路，卷上珠帘总不如。",
    translation: "她姿态娉婷袅娜、才十三有余，像二月初豆蔻梢头的花。春风十里的扬州路上，卷起珠帘看来总比不上她。",
