    title: "赠别·其二",
    entries: ["tangshi-ts-288"],
    text: "多情却似总无情，惟觉樽前笑不成。\n蜡烛有心还惜别，替人垂泪到天明。",
    translation: "多情却像是总无情，只觉得在酒樽前笑不出来。蜡烛有心、还懂得惜别，替人流泪直到天明。",
