    title: "瑶瑟怨",
    entries: ["tangshi-ts-289"],
    text: "冰簟银床梦不成，碧天如水夜云轻。\n雁声远过潇湘去，十二楼中月自明。",
    translation: "冰凉的竹席、银色的床、梦也做不成，碧天如水、夜云轻淡。雁声远远地越过潇湘而去，十二楼中明月自照。",
