    id: "tangshi-ts-319",
    title: "从军行",
    entries: ["tangshi-ts-319"],
    text: "烽火照西京，心中自不平。\n牙璋辞凤阙，铁骑绕龙城。\n雪暗凋旗画，风多杂鼓声。\n宁为百夫长，胜作一书生。",
    translation: "边塞烽火映照长安，我心中自然激愤难平。\n兵符辞别朝廷，精锐骑兵直逼敌城。\n大雪昏暗使军旗彩画褪色，狂风呼啸夹杂着战鼓声。\n我宁愿做一名百夫长冲锋陷阵，也胜过做只会读书的书生。",
