    title: "登太白峰",
    entries: ["tangshi-ts-325"],
    text: "西上太白峰，夕阳穷登攀。\n太白与我语，为我开天关。\n愿乘泠风去，直出浮云间。\n举手可近月，前行若无山。\n一别武功去，何时复更还？",
