    id: "tangshi-ts-332",
    title: "宿骆氏亭寄怀崔雍崔衮",
    entries: ["tangshi-ts-332"],
    text: "竹坞无尘水槛清，相思迢递隔重城。\n秋阴不散霜飞晚，留得枯荷听雨声。",
    translation: "竹林环绕的船坞洁净无尘，临水的栏杆清幽，思念迢迢隔着重重城池。\n秋日阴云不散霜落得晚，只留下枯败的荷叶听那雨声。",
