    title: "题宣州开元寺水阁",
    entries: ["tangshi-ts-339"],
    text: "六朝文物草连空，天淡云闲今古同。\n鸟去鸟来山色里，人歌人哭水声中。\n深秋帘幕千家雨，落日楼台一笛风。\n惆怅无因见范蠡，参差烟树五湖东。",
