    entries: ["tangshi-ts-343"],
    text: "胡马大宛名，锋棱瘦骨成。\n竹批双耳峻，风入四蹄轻。\n所向无空阔，真堪托死生。\n骁腾有如此，万里可横行。",
    translation: "这匹胡马有着大宛马的美名，矫健的骨相棱角分明。\n双耳像削尖的竹筒一样挺立，四蹄生风轻快无比。\n所到之处不论多么空阔，都足以把生死托付给它。\n勇猛矫健到这般地步，万里之外也可纵横驰骋。",
