    entries: ["tangshi-ts-344"],
    text: "素练风霜起，苍鹰画作殊。\n㩳身思狡兔，侧目似愁胡。\n绦镟光堪摘，轩楹势可呼。\n何当击凡鸟，毛血洒平芜。",
