    entries: ["tangshi-ts-35"],
    text: "主人有酒欢今夕，请奏鸣琴广陵客。\n月照城头乌半飞，霜凄万树风入衣。\n铜炉华烛烛增辉，初弹渌水后楚妃。\n一声已动物皆静，四座无言星欲稀。\n清淮奉使千余里，敢告云山从此始。",
    translation: "主人备酒，今夜欢聚，请来善弹琴的广陵客为我奏一曲。月光照着城头，乌鸦半飞；霜气凄冷万树，寒风吹入衣裳。铜炉香料、华美蜡烛使烛光更亮，先弹《渌水》，后弹《楚妃》。琴声一起，万物都静了下来，满座无言，直到天将亮、星星稀疏。我奉命出使清淮，路远千里，从此要辞别云山开始了。",
