    title: "宿云门寺阁",
    entries: ["tangshi-ts-358"],
    text: "香阁东山下，烟花象外幽。\n悬灯千嶂夕，卷幔五湖秋。\n画壁余鸿雁，纱窗宿斗牛。\n更疑天路近，梦与白云游。",
