    entries: ["tangshi-ts-450"],
    text: "霜草苍苍虫切切，村南村北行人绝。\n独出门前望野田，月明荞麦花如雪。",
    translation: "经霜的野草一片苍苍，秋虫切切地鸣叫，村南村北已没有行人。我独自走到门前眺望田野，月光下荞麦花白得像雪一样。",
