    text: "绿树阴浓夏日长，楼台倒影入池塘。\n水晶帘动微风起，满架蔷薇一院香。",
    translation: "绿树浓荫，夏日的白昼显得格外漫长；楼台的倒影映在池塘里。微风一起，水晶帘子轻轻摇动，满架蔷薇送来一院子的香气。",
