    entries: ["tangshi-ts-84"],
    text: "汉家烟尘在东北，汉将辞家破残贼。\n男儿本自重横行，天子非常赐颜色。\n摐金伐鼓下榆关，旌旆逶迤碣石间。\n校尉羽书飞瀚海，单于猎火照狼山。\n山川萧条极边土，胡骑凭陵杂风雨。\n战士军前半死生，美人帐下犹歌舞。",
    translation: "（此篇咏边塞征战，与高适《燕歌行》同调。）汉家的烟尘起在东北，汉将辞别家人去破击残贼。男儿本来自重、横行沙场，天子格外赐予恩遇。敲锣击鼓开下榆关，旌旗曲折行进在碣石之间。校尉的紧急军书飞过瀚海，单于的猎火照到狼山。山川萧条直到极远的边土，胡骑凭陵侵扰、夹杂着风雨。战士在阵前出生入死，美人还在帐下歌舞。",
