    title: "玉阶怨",
    entries: ["tangshi-ts-93", "yuefu-yf-62"],
    text: "玉阶生白露，夜久侵罗袜。\n却下水晶帘，玲珑望秋月。",
    translation: "玉石台阶上生出白露，夜深了露水浸湿了罗袜。只好放下水晶帘，隔着玲珑的帘子望着秋月。",
